//! Unity TexturePacker text format 40300, rectangular sprites without trimming or rotation.
use std::{collections::HashSet,fmt::Write as _,path::{Path,PathBuf}};

pub(super) fn encode(texture:&Path,size:(u32,u32),files:&[PathBuf],bounds:&[[u32;6]])->Result<String,String> {
    if files.len()!=bounds.len(){return Err("Sprite count mismatch".into())}
    let mut text=format!("# Sprite sheet data for Unity.
# Generated by Unity YAML Viewer.
:format=40300
:texture={}
:size={}x{}
:pivotpoints=enabled
:borders=disabled
:alphahandling=ClearTransparentPixels
",texture.file_name().unwrap_or_default().to_string_lossy(),size.0,size.1);
    let mut used=HashSet::new();
    for (file,&[x,y,w,h,_,_]) in files.iter().zip(bounds) {
        if w==0||h==0||x.checked_add(w).is_none_or(|v|v>size.0)||y.checked_add(h).is_none_or(|v|v>size.1){return Err("Sprite rectangle outside texture".into())}
        let stem=file.file_stem().unwrap_or_default().to_string_lossy();
        let stem:String=stem.chars().map(|c|if c==';'||c.is_control(){'_'}else{c}).collect();
        let stem=if stem.is_empty()||stem.starts_with(['#',':']){format!("sprite_{stem}")}else{stem};
        let mut name=stem.clone();let mut suffix=2;
        while !used.insert(name.to_lowercase()){name=format!("{stem}_{suffix}");suffix+=1;}
        // Unity uses a bottom-left origin. Geometry is local to the sprite rectangle.
        writeln!(text,"{name};{x};{};{w};{h};0.5;0.5;0;0;0;0;4;{w};0;0;0;0;{h};{w};{h};2;1;2;3;0;1;3",size.1-y-h).unwrap();
    }
    Ok(text)
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn exact_rectangles_names_and_bottom_left_coordinates(){
        let files=vec![PathBuf::from("a/frame.png"),PathBuf::from("b/frame.png")];
        let text=encode(Path::new("sheet.png"),(128,256),&files,&[[3,7,51,52,100,100],[64,100,32,40,100,100]]).unwrap();
        assert!(text.contains(":format=40300
:texture=sheet.png
:size=128x256"));
        assert!(text.contains("frame;3;197;51;52;0.5;0.5"));
        assert!(text.contains("frame_2;64;116;32;40;0.5;0.5"));
        assert_eq!(text.lines().filter(|line|!line.starts_with(['#',':'])).count(),2);
        assert!(encode(Path::new("sheet.png"),(1,1),&files,&[]).is_err());
    }
}
